// The batch reference program (wiki: programs/batch): several calls in one
// transaction, in order, all or none. This is how an operation that pays no
// miner itself, such as a cancel from a time-locked account or a registry
// operation, travels with a fee paid by another account. A payment that
// sponsors the calls before it is bound to them with the coin's `within`
// condition and the progress prefix of those calls, so a miner cannot take it
// out of the batch.
import { Reader, Writer, tryDecode, u32le } from './bytes';
import { taggedHash } from './hash';

export const BATCH_PREFIX_TAG = 'app/batch/prefix';

/** Input `00`: a query for the progress prefix of the batch running now. */
export const BATCH_QUERY = Uint8Array.of(0);

export interface BatchCall {
  target: Uint8Array;
  input: Uint8Array;
}

/** `call*`, each `target(32) ‖ Bytes(input)`, back to back. */
export function batchInput(calls: BatchCall[]): Uint8Array {
  const w = new Writer();
  for (const c of calls) {
    if (c.target.length !== 32) throw new RangeError('a call target is 32 bytes');
    w.put(c.target).bytes(c.input);
  }
  return w.finish();
}

/** The result of a successful batch: each call's result, in order. */
export function decodeBatchResult(bytes: Uint8Array): Uint8Array[] | null {
  return tryDecode(() => {
    const r = new Reader(bytes);
    const out: Uint8Array[] = [];
    while (r.remaining > 0) out.push(new Uint8Array(r.bytes()));
    return out;
  });
}

/** The prefix before the first call: `H("app/batch/prefix", "")`. */
export function batchPrefixStart(): Uint8Array {
  return taggedHash(BATCH_PREFIX_TAG);
}

/** The prefix after one more call: `H("app/batch/prefix", prefix ‖ target ‖ Bytes(input))`. */
export function batchPrefixNext(prefix: Uint8Array, call: BatchCall): Uint8Array {
  return taggedHash(BATCH_PREFIX_TAG, prefix, call.target, u32le(call.input.length), call.input);
}

/** The prefix after `calls`: what a sponsoring payment placed right after them names. */
export function batchPrefix(calls: BatchCall[]): Uint8Array {
  return calls.reduce(batchPrefixNext, batchPrefixStart());
}
